FILES={"seed_approval_resolver_v13623.py": "import json, os, re, sys, time\nfrom pathlib import Path\nfrom datetime import datetime\n\nVERSION = \"v136.2.3\"\nSUPPRESS = Path(\"seed_approval_resolver_v13623_suppressed.json\")\nEVENTS = Path(\"seed_approval_resolver_v13623_events.jsonl\")\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef event(row):\n    row.setdefault(\"created_at\", now())\n    row.setdefault(\"version\", VERSION)\n    with EVENTS.open(\"a\") as f:\n        f.write(json.dumps(row, ensure_ascii=False) + \"\\n\")\n    return row\n\ndef load_suppressed():\n    if SUPPRESS.exists():\n        try:\n            obj = json.loads(SUPPRESS.read_text(errors=\"ignore\"))\n            if isinstance(obj, dict):\n                obj.setdefault(\"version\", VERSION)\n                obj.setdefault(\"suppressed\", [])\n                return obj\n        except Exception:\n            pass\n    obj = {\"version\": VERSION, \"created_at\": now(), \"suppressed\": []}\n    SUPPRESS.write_text(json.dumps(obj, indent=4, ensure_ascii=False))\n    return obj\n\ndef save_suppressed(obj):\n    obj[\"version\"] = VERSION\n    obj[\"updated_at\"] = now()\n    SUPPRESS.write_text(json.dumps(obj, indent=4, ensure_ascii=False))\n    return obj\n\ndef rid(item):\n    if not isinstance(item, dict):\n        return None\n    for k in [\"request_id\", \"id\", \"approval_id\", \"uid\"]:\n        if item.get(k):\n            return str(item.get(k))\n    m = re.search(r\"[a-f0-9]{12,}\", json.dumps(item, ensure_ascii=False).lower())\n    return m.group(0) if m else None\n\ndef app():\n    import seed_action_approval_v107 as a\n    return a\n\ndef raw_status():\n    try:\n        a = app()\n        st = a.status()\n        pending = []\n        for key in [\"pending\", \"requests\", \"items\", \"approvals\"]:\n            if isinstance(st.get(key), list):\n                pending = st[key]\n                break\n        resolved_ids = set()\n        approved_ids = set()\n        auto_ids = set()\n        for key in [\"resolved\", \"rejected\", \"denied\", \"auto_resolved\"]:\n            if isinstance(st.get(key), list):\n                for x in st[key]:\n                    r = rid(x)\n                    if r:\n                        resolved_ids.add(r)\n                        if key == \"auto_resolved\":\n                            auto_ids.add(r)\n        if isinstance(st.get(\"resolved_ids\"), list):\n            resolved_ids.update(map(str, st.get(\"resolved_ids\")))\n        if isinstance(st.get(\"approved_ids\"), list):\n            approved_ids.update(map(str, st.get(\"approved_ids\")))\n        if isinstance(st.get(\"approvals\"), list):\n            for x in st.get(\"approvals\", []):\n                r = rid(x)\n                if r:\n                    if x.get(\"approved\") is True:\n                        approved_ids.add(r)\n                    elif x.get(\"approved\") is False:\n                        resolved_ids.add(r)\n        return {\n            \"ok\": True,\n            \"status\": st,\n            \"pending\": pending,\n            \"pending_count\": int(st.get(\"pending_count\", len(pending)) or 0),\n            \"resolved_ids\": sorted(resolved_ids),\n            \"approved_ids\": sorted(approved_ids),\n            \"auto_resolved_ids\": sorted(auto_ids)\n        }\n    except Exception as e:\n        return {\"ok\": False, \"error\": str(e), \"pending\": [], \"pending_count\": 0}\n\ndef suppressed_ids():\n    return {str(x.get(\"request_id\")) for x in load_suppressed().get(\"suppressed\", []) if x.get(\"request_id\")}\n\ndef suppress(request_id, reason=\"manual_suppress\", item=None):\n    if not request_id:\n        return {\"ok\": False, \"error\": \"missing request_id\"}\n    obj = load_suppressed()\n    existing = {x.get(\"request_id\") for x in obj.get(\"suppressed\", [])}\n    if request_id not in existing:\n        obj[\"suppressed\"].append({\"request_id\": str(request_id), \"reason\": reason, \"item\": item, \"created_at\": now(), \"version\": VERSION})\n        save_suppressed(obj)\n    row = {\"ok\": True, \"request_id\": str(request_id), \"reason\": reason}\n    event({\"event\": \"suppress\", **row})\n    return row\n\ndef call_reject(request_id, reason=\"seed approval resolver\"):\n    try:\n        a = app()\n    except Exception as e:\n        return {\"ok\": False, \"error\": str(e)}\n    tried = []\n    for name in [\"reject\", \"deny\", \"decline\", \"resolve\"]:\n        fn = getattr(a, name, None)\n        if not callable(fn):\n            continue\n        patterns = [\n            ((request_id,), {}),\n            ((request_id, reason), {}),\n            ((), {\"request_id\": request_id, \"reason\": reason}),\n            ((), {\"approval_id\": request_id, \"reason\": reason}),\n            ((), {\"id\": request_id, \"reason\": reason}),\n        ]\n        for args, kwargs in patterns:\n            try:\n                res = fn(*args, **kwargs)\n                return {\"ok\": True, \"function\": name, \"request_id\": request_id, \"result\": res}\n            except Exception as e:\n                tried.append({\"function\": name, \"args\": list(args), \"kwargs\": kwargs, \"error\": str(e)})\n    return {\"ok\": False, \"error\": \"no reject function worked\", \"tried\": tried}\n\ndef call_approve(request_id, reason=\"seed approval resolver\"):\n    try:\n        a = app()\n    except Exception as e:\n        return {\"ok\": False, \"error\": str(e)}\n    tried = []\n    for name in [\"approve\", \"allow\", \"grant\"]:\n        fn = getattr(a, name, None)\n        if not callable(fn):\n            continue\n        patterns = [\n            ((request_id,), {}),\n            ((request_id, reason), {}),\n            ((), {\"request_id\": request_id, \"reason\": reason}),\n            ((), {\"approval_id\": request_id, \"reason\": reason}),\n            ((), {\"id\": request_id, \"reason\": reason}),\n        ]\n        for args, kwargs in patterns:\n            try:\n                res = fn(*args, **kwargs)\n                return {\"ok\": True, \"function\": name, \"request_id\": request_id, \"result\": res}\n            except Exception as e:\n                tried.append({\"function\": name, \"args\": list(args), \"kwargs\": kwargs, \"error\": str(e)})\n    return {\"ok\": False, \"error\": \"no approve function worked\", \"tried\": tried}\n\ndef is_stale_empty_operator(item):\n    if not isinstance(item, dict):\n        return False\n    action = str(item.get(\"action\",\"\")).lower()\n    if action not in {\"operator type\", \"operator key\", \"operator hotkey\", \"operator paste\", \"operator click\"}:\n        return False\n    if item.get(\"command\") or item.get(\"target\"):\n        return False\n    try:\n        created = datetime.fromisoformat(str(item.get(\"created_at\",\"\")))\n        age = (datetime.now() - created).total_seconds() / 60\n    except Exception:\n        age = 999999\n    return age >= 90\n\ndef effective_status():\n    rs = raw_status()\n    if not rs.get(\"ok\"):\n        return rs\n    suppressed = suppressed_ids()\n    resolved = set(rs.get(\"resolved_ids\", [])) | suppressed\n    effective = []\n    filtered = []\n    for item in rs.get(\"pending\", []):\n        request_id = rid(item)\n        if request_id in resolved:\n            filtered.append({\"request_id\": request_id, \"reason\": \"resolved_or_suppressed\", \"item\": item})\n            continue\n        effective.append(item)\n    out = {\n        \"created_at\": now(),\n        \"version\": VERSION,\n        \"ok\": True,\n        \"raw_pending_count\": rs.get(\"pending_count\"),\n        \"effective_pending_count\": len(effective),\n        \"effective_pending\": effective,\n        \"filtered\": filtered,\n        \"suppressed_ids\": sorted(suppressed),\n        \"resolved_ids\": rs.get(\"resolved_ids\", []),\n        \"raw\": rs\n    }\n    return out\n\ndef repair_stale(apply=False):\n    st = effective_status()\n    actions = []\n    for item in st.get(\"effective_pending\", []):\n        request_id = rid(item)\n        if is_stale_empty_operator(item):\n            row = {\"request_id\": request_id, \"item\": item, \"decision\": \"reject_and_suppress\", \"applied\": False}\n            if apply:\n                row[\"reject\"] = call_reject(request_id, \"Auto-rejected stale empty operator request by v136.2.3 resolver\")\n                row[\"suppress\"] = suppress(request_id, \"stale_empty_operator_request\", item=item)\n                row[\"applied\"] = True\n            actions.append(row)\n    out = {\"created_at\": now(), \"version\": VERSION, \"ok\": True, \"apply\": apply, \"before\": st, \"actions\": actions}\n    event({\"event\": \"repair_stale\", \"apply\": apply, \"action_count\": len(actions), \"actions\": actions})\n    return out\n\ndef apply_reject_and_suppress(request_id):\n    res = call_reject(request_id, \"Rejected and suppressed by v136.2.3 resolver\")\n    sup = suppress(request_id, \"manual_reject_and_suppress\")\n    event({\"event\": \"reject_and_suppress\", \"request_id\": request_id, \"reject\": res, \"suppress\": sup})\n    return {\"ok\": bool(res.get(\"ok\") or sup.get(\"ok\")), \"reject\": res, \"suppress\": sup, \"effective_status\": effective_status()}\n\ndef apply_approve(request_id):\n    res = call_approve(request_id, \"Approved by v136.2.3 resolver\")\n    event({\"event\": \"approve\", \"request_id\": request_id, \"result\": res})\n    return {\"ok\": bool(res.get(\"ok\")), \"approve\": res, \"effective_status\": effective_status()}\n\ndef test():\n    dry = repair_stale(False)\n    st = effective_status()\n    return {\"ok\": True, \"dry_run_ok\": dry.get(\"ok\"), \"effective_pending_count\": st.get(\"effective_pending_count\"), \"raw_pending_count\": st.get(\"raw_pending_count\")}\n\nif __name__ == \"__main__\":\n    cmd = sys.argv[1] if len(sys.argv) > 1 else \"status\"\n    if cmd == \"raw\":\n        print(json.dumps(raw_status(), indent=4, ensure_ascii=False))\n    elif cmd == \"status\":\n        print(json.dumps(effective_status(), indent=4, ensure_ascii=False))\n    elif cmd == \"repair-stale\":\n        print(json.dumps(repair_stale(\"--apply\" in sys.argv), indent=4, ensure_ascii=False))\n    elif cmd == \"suppress\":\n        print(json.dumps(suppress(sys.argv[2] if len(sys.argv)>2 else None, \"manual\"), indent=4, ensure_ascii=False))\n    elif cmd == \"reject\":\n        print(json.dumps(apply_reject_and_suppress(sys.argv[2] if len(sys.argv)>2 else None), indent=4, ensure_ascii=False))\n    elif cmd == \"approve\":\n        print(json.dumps(apply_approve(sys.argv[2] if len(sys.argv)>2 else None), indent=4, ensure_ascii=False))\n    elif cmd == \"test\":\n        print(json.dumps(test(), indent=4, ensure_ascii=False))\n    else:\n        print(json.dumps(effective_status(), indent=4, ensure_ascii=False))\n", "seed_approval_autopilot_v13623.py": "import json, os, signal, subprocess, sys, time\nfrom pathlib import Path\nfrom datetime import datetime\n\nVERSION = \"v136.2.3\"\nPID = Path(\"seed_approval_autopilot_v13623.pid\")\nLOG = Path(\"seed_approval_autopilot_v13623.log\")\nEVENTS = Path(\"seed_approval_autopilot_v13623_events.jsonl\")\nSETTINGS = Path(\"seed_approval_autopilot_v13623_settings.json\")\n\nDEFAULT = {\"version\": VERSION, \"enabled\": True, \"interval_seconds\": 5, \"apply\": True}\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef settings():\n    if SETTINGS.exists():\n        try:\n            obj=json.loads(SETTINGS.read_text(errors=\"ignore\"))\n            if isinstance(obj,dict):\n                base=DEFAULT.copy(); base.update(obj); base[\"version\"]=VERSION; return base\n        except Exception: pass\n    SETTINGS.write_text(json.dumps(DEFAULT, indent=4, ensure_ascii=False))\n    return DEFAULT.copy()\n\ndef event(row):\n    row.setdefault(\"created_at\", now())\n    row.setdefault(\"version\", VERSION)\n    with EVENTS.open(\"a\") as f:\n        f.write(json.dumps(row, ensure_ascii=False)+\"\\n\")\n    return row\n\ndef alive(pid):\n    try:\n        os.kill(int(pid),0); return True\n    except Exception: return False\n\ndef resolve_once(apply=True):\n    import seed_approval_resolver_v13623 as resolver\n    import seed_autonomy_policy_v13622 as policy\n    st = resolver.effective_status()\n    actions = []\n    for item in st.get(\"effective_pending\", []):\n        dec = policy.decision_for(item)\n        request_id = resolver.rid(item)\n        row = {\"request_id\": request_id, \"item\": item, \"decision\": dec, \"applied\": False}\n        if dec.get(\"decision\") == \"auto_reject\":\n            if apply:\n                row[\"result\"] = resolver.apply_reject_and_suppress(request_id)\n                row[\"applied\"] = bool(row[\"result\"].get(\"ok\"))\n            actions.append(row)\n        elif dec.get(\"decision\") == \"auto_approve\":\n            if apply:\n                row[\"result\"] = resolver.apply_approve(request_id)\n                row[\"applied\"] = bool(row[\"result\"].get(\"ok\"))\n            actions.append(row)\n        else:\n            actions.append(row)\n    # Also catch the stale-empty request even if policy was not loaded/matched.\n    stale = resolver.repair_stale(apply=apply)\n    for a in stale.get(\"actions\", []):\n        if not any(x.get(\"request_id\") == a.get(\"request_id\") for x in actions):\n            actions.append({\"request_id\": a.get(\"request_id\"), \"decision\": {\"decision\": \"auto_reject\", \"reason\": \"stale_empty_operator_request\"}, \"result\": a, \"applied\": apply})\n    after = resolver.effective_status()\n    out = {\"created_at\": now(), \"version\": VERSION, \"ok\": True, \"apply\": apply, \"before\": st, \"actions\": actions, \"after\": after}\n    event({\"event\":\"resolve_once\",\"apply\":apply,\"action_count\":len(actions),\"raw_pending_before\":st.get(\"raw_pending_count\"),\"effective_pending_after\":after.get(\"effective_pending_count\"),\"actions\":actions})\n    return out\n\ndef daemon():\n    event({\"event\":\"daemon_started\",\"pid\":os.getpid()})\n    while True:\n        s=settings()\n        if s.get(\"enabled\", True):\n            try:\n                resolve_once(apply=bool(s.get(\"apply\", True)))\n            except Exception as e:\n                event({\"event\":\"daemon_error\",\"error\":str(e)})\n        time.sleep(float(s.get(\"interval_seconds\", 5)))\n\ndef start():\n    if PID.exists():\n        try:\n            pid=int(PID.read_text().strip())\n            if alive(pid):\n                return {\"ok\":True,\"already_running\":True,\"pid\":pid}\n        except Exception: pass\n    # Stop old v13622 autopilot so it doesn't spam duplicate rejects.\n    try:\n        import seed_approval_autopilot_v13622 as old\n        old.stop()\n    except Exception:\n        pass\n    p=subprocess.Popen([sys.executable,\"seed_approval_autopilot_v13623.py\",\"daemon\"],stdout=LOG.open(\"a\"),stderr=LOG.open(\"a\"))\n    PID.write_text(str(p.pid))\n    return {\"ok\":True,\"pid\":p.pid}\n\ndef stop():\n    pid=None; stopped=False\n    if PID.exists():\n        try:\n            pid=int(PID.read_text().strip())\n            if alive(pid): os.kill(pid,signal.SIGTERM); stopped=True\n            PID.unlink(missing_ok=True)\n        except Exception: pass\n    event({\"event\":\"daemon_stopped\",\"pid\":pid,\"stopped\":stopped})\n    return {\"ok\":True,\"stopped\":stopped,\"pid\":pid}\n\ndef status():\n    pid=None; al=False\n    if PID.exists():\n        try: pid=int(PID.read_text().strip()); al=alive(pid)\n        except Exception: pass\n    recent=[]\n    if EVENTS.exists():\n        for line in EVENTS.read_text(errors=\"ignore\").splitlines()[-10:]:\n            try: recent.append(json.loads(line))\n            except Exception: pass\n    import seed_approval_resolver_v13623 as resolver\n    return {\"created_at\":now(),\"version\":VERSION,\"ok\":True,\"alive\":al,\"pid\":pid,\"settings\":settings(),\"effective_approval_status\":resolver.effective_status(),\"recent_events\":recent}\n\ndef test():\n    return {\"ok\": True, \"dry_run\": resolve_once(False), \"status\": status()}\n\nif __name__==\"__main__\":\n    cmd=sys.argv[1] if len(sys.argv)>1 else \"status\"\n    if cmd==\"daemon\": daemon()\n    elif cmd==\"start\": print(json.dumps(start(),indent=4,ensure_ascii=False))\n    elif cmd==\"stop\": print(json.dumps(stop(),indent=4,ensure_ascii=False))\n    elif cmd in {\"once\",\"apply\"}: print(json.dumps(resolve_once(True),indent=4,ensure_ascii=False))\n    elif cmd in {\"dry-run\",\"preview\"}: print(json.dumps(resolve_once(False),indent=4,ensure_ascii=False))\n    elif cmd==\"test\": print(json.dumps(test(),indent=4,ensure_ascii=False))\n    else: print(json.dumps(status(),indent=4,ensure_ascii=False))\n", "seed_hygiene_status_v13623.py": "import json, sys\nfrom datetime import datetime\n\nVERSION=\"v136.2.3\"\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef base_scan():\n    try:\n        import seed_hygiene_center_v1362 as h\n        return h.scan()\n    except Exception as e:\n        return {\"ok\":False,\"error\":str(e)}\n\ndef scan():\n    b = base_scan()\n    try:\n        import seed_approval_resolver_v13623 as resolver\n        eff = resolver.effective_status()\n        b[\"approval_v13623\"] = eff\n        # Override visible pending count with effective pending count.\n        if isinstance(b.get(\"approval\"), dict):\n            b[\"approval\"][\"raw_pending_count\"] = b[\"approval\"].get(\"pending_count\")\n            b[\"approval\"][\"pending_count\"] = eff.get(\"effective_pending_count\")\n            b[\"approval\"][\"pending_effective\"] = eff.get(\"effective_pending\")\n            b[\"approval\"][\"filtered\"] = eff.get(\"filtered\")\n        # Re-score with fixed approval count.\n        reasons = []\n        score = 100\n        if not b.get(\"runtime\",{}).get(\"alive\"):\n            score -= 10; reasons.append(\"voice_runtime_not_alive\")\n        pc = eff.get(\"effective_pending_count\") or 0\n        if pc:\n            score -= min(25, pc*15); reasons.append(f\"{pc}_pending_approval\")\n        tc = b.get(\"tasks\",{}).get(\"test_task_count\") or 0\n        if tc:\n            score -= min(20, tc*15); reasons.append(f\"{tc}_test_task\")\n        dc = b.get(\"memory\",{}).get(\"duplicate_count\") or 0\n        if dc:\n            score -= min(20, dc*4); reasons.append(f\"{dc}_duplicate_memory_entries\")\n        if b.get(\"logs\",{}).get(\"large_logs\"):\n            score -= 5; reasons.append(\"large_logs\")\n        b[\"hygiene_v13623\"] = {\"score\": max(0, score), \"reasons\": reasons, \"grade\": \"clean\" if score>=90 else \"needs_review\" if score>=70 else \"dirty\"}\n    except Exception as e:\n        b[\"approval_v13623_error\"] = str(e)\n    b[\"created_at_v13623\"] = now()\n    b[\"version_v13623\"] = VERSION\n    return b\n\ndef text():\n    d=scan()\n    h=d.get(\"hygiene_v13623\") or d.get(\"hygiene\",{})\n    lines=[\n        \"Seed v136.2.3 Effective Hygiene Status\",\n        f\"Hygiene score: {h.get('score')}/100 ({h.get('grade')})\",\n        f\"Reasons: {', '.join(h.get('reasons',[])) or 'none'}\",\n        f\"Voice runtime: {'alive' if d.get('runtime',{}).get('alive') else 'stopped'} pid={d.get('runtime',{}).get('pid')}\",\n        f\"Approvals pending effective: {d.get('approval_v13623',{}).get('effective_pending_count')}\",\n        f\"Approvals pending raw: {d.get('approval_v13623',{}).get('raw_pending_count')}\",\n        f\"Open tasks: {d.get('tasks',{}).get('open_count')} / test tasks: {d.get('tasks',{}).get('test_task_count')}\",\n        f\"Memory count: {d.get('memory',{}).get('memory_count')} / duplicate entries: {d.get('memory',{}).get('duplicate_count')}\",\n        f\"Last answer: {d.get('runtime',{}).get('last_answer')}\",\n    ]\n    return \"\\n\".join(lines)\n\nif __name__==\"__main__\":\n    if \"--json\" in sys.argv:\n        print(json.dumps(scan(), indent=4, ensure_ascii=False))\n    else:\n        print(text())\n", "seed_v13623_approval_fix_gate.py": "import json, subprocess, sys\nfrom pathlib import Path\nfrom datetime import datetime\n\nMODULES=[\"seed_approval_resolver_v13623.py\",\"seed_approval_autopilot_v13623.py\",\"seed_hygiene_status_v13623.py\",\"seed_v13623_approval_fix_gate.py\"]\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef comp(m):\n    p=subprocess.run([sys.executable,\"-m\",\"py_compile\",m],capture_output=True,text=True,timeout=30)\n    return {\"module\":m,\"ok\":p.returncode==0,\"stderr\":p.stderr[-1000:]}\n\ndef run_gate():\n    checks=[comp(m) for m in MODULES]\n    modules_ok=all(c[\"ok\"] for c in checks)\n    details={}\n    try:\n        import seed_approval_resolver_v13623 as r\n        rt=r.test()\n        details[\"resolver_test\"]=rt\n        resolver_ok=rt.get(\"ok\") is True\n    except Exception as e:\n        resolver_ok=False; details[\"resolver_error\"]=str(e)\n    try:\n        import seed_approval_autopilot_v13623 as a\n        at=a.test()\n        details[\"autopilot_test\"]=at\n        autopilot_ok=at.get(\"ok\") is True\n    except Exception as e:\n        autopilot_ok=False; details[\"autopilot_error\"]=str(e)\n    try:\n        import seed_hygiene_status_v13623 as h\n        hs=h.scan()\n        details[\"hygiene_status\"]={\"hygiene_v13623\":hs.get(\"hygiene_v13623\"),\"approval_v13623\":hs.get(\"approval_v13623\")}\n        hygiene_ok=\"hygiene_v13623\" in hs\n    except Exception as e:\n        hygiene_ok=False; details[\"hygiene_error\"]=str(e)\n    report={\"created_at\":now(),\"version\":\"v136.2.3\",\"ready\":modules_ok and resolver_ok and autopilot_ok and hygiene_ok,\"modules_ok\":modules_ok,\"resolver_ok\":resolver_ok,\"autopilot_ok\":autopilot_ok,\"hygiene_ok\":hygiene_ok,\"checks\":checks,\"details\":details}\n    Path(\"seed_v13623_approval_fix_gate_report.json\").write_text(json.dumps(report,indent=4,ensure_ascii=False))\n    return report\n\ndef show():\n    r=run_gate()\n    print(\"\\n=== SEED v136.2.3 APPROVAL LOOP FIX GATE ===\")\n    print(f\"Ready: {r['ready']}\")\n    print(f\"Modules OK: {r['modules_ok']}\")\n    print(f\"Resolver OK: {r['resolver_ok']}\")\n    print(f\"Autopilot OK: {r['autopilot_ok']}\")\n    print(f\"Hygiene Status OK: {r['hygiene_ok']}\")\n    try:\n        eff=r[\"details\"][\"hygiene_status\"][\"approval_v13623\"]\n        hyg=r[\"details\"][\"hygiene_status\"][\"hygiene_v13623\"]\n        print(f\"Effective approvals pending: {eff.get('effective_pending_count')}\")\n        print(f\"Raw approvals pending: {eff.get('raw_pending_count')}\")\n        print(f\"Effective hygiene score: {hyg.get('score')}/100\")\n    except Exception:\n        pass\n\nif __name__==\"__main__\":\n    show()\n"}
